<?php require 'header.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){echo '<div class="container empty">ไม่พบสินค้า</div>';require 'footer.php';exit;} ?>
<div class="container"><div class="detail"><div><?php if($p['image']):?><img src="<?=h($p['image'])?>" alt="<?=h($p['name'])?>"><?php else:?><div class="placeholder" style="height:360px">🖥</div><?php endif;?></div><div><span class="badge"><?=h($p['category']??'สินค้า PC')?></span><h1><?=h($p['name'])?></h1><div class="price" style="font-size:30px">฿<?=money($p['price'])?></div><p class="muted">มีสินค้า <?=h($p['stock'])?> ชิ้น</p><p><?=nl2br(h($p['description']))?></p><?php if(user()):?><form action="cart.php" method="post" class="inline"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="hidden" name="add" value="1"><label>จำนวน</label><input style="width:90px" type="number" min="1" max="<?=$p['stock']?>" name="quantity" value="1"><button class="btn" <?=$p['stock']<1?'disabled':''?>>เพิ่มลงตะกร้า</button></form><form action="wishlist.php" method="post" style="margin-top:10px"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="btn secondary">♡ เพิ่มรายการโปรด</button></form><?php else:?><a class="btn" href="login.php">เข้าสู่ระบบเพื่อสั่งซื้อ</a><?php endif;?></div></div></div><?php require 'footer.php';?>
